from rcb_molmospaces import Session
import numpy as np
s=Session('/app/instance.json'); p=s.proprio()['tcp_pose']; q0=p[3:].tolist()
rots=[[1,0,0,0],[0.7071,0,0.7071,0],[0.7071,0,0,0.7071],[0.7071,0.7071,0,0],[0.5,0.5,0.5,0.5],q0]
for xyz in [[1.4,-1.0,2.1],[1.5,-1.0,2.1],[1.5,-.9,2.1],[1.5,-.9,2.3],[1.55,-.9,2.2],[1.55,-.9,2.35],[1.6,-.9,2.2]]:
 for q in rots:
  r=s.kinematics({'op':'ik','targets':{'gripper':xyz+q}})
  if r['ok']: print('ok xyz',xyz,'q',q,'ik',np.round(r['q'],2).tolist(),'err',r['error'])
