from rcb_molmospaces import Session
import numpy as np, json, mujoco
s=Session('/app/instance.json'); q0=s.proprio()['joint_pos']; p=s.proprio()['tcp_pose']; q=q0.copy()
poses=[
 [1.30,-1.05,2.10,*p[3:]],
 [1.34,-.80,2.05,*p[3:]],
 [1.42,-.65,1.95,*p[3:]],
 [1.50,-.55,1.82,*p[3:]],
 [1.62,-.48,1.72,*p[3:]],
]
qs=[]
for pose in poses:
 r=s.kinematics({'op':'ik','seed':q.tolist(),'targets':{'gripper':pose}})
 if not r['ok']: raise RuntimeError((pose,r))
 q=np.array(r['q']); qs.append(q); print('IK',pose[:3],np.round(q,2).tolist(),flush=True)
rows=[]; prev=q0
for target in qs:
 n=max(10,int(np.max(np.abs(target-prev))/.05)+1)
 for a in np.linspace(0,1,n+1)[1:]: rows.append(np.r_[prev*(1-a)+target*a,0.])
 for _ in range(4): rows.append(np.r_[target,0.])
 prev=target
for _ in range(45): rows.append(np.r_[prev,0.])
for i,row in enumerate(rows):
 s.step(row)
 if (i+1)%25==0: print('STEP',i+1,'success',s.status()['success'],'add',s.state()['joints'].get('cabinet_add263c1fa0598f1e8a8f6355900bc96_1_1_0_joint_0'),'target6',s.state()['joints'].get('cabinet_6cd68b05840d772941331ceec311d697_1_1_0_joint_0'),flush=True)
contacts=[]
for ci in range(s.data.ncon):
 c=s.data.contact[ci]; g1=mujoco.mj_id2name(s.model,mujoco.mjtObj.mjOBJ_GEOM,c.geom1);g2=mujoco.mj_id2name(s.model,mujoco.mjtObj.mjOBJ_GEOM,c.geom2)
 b1=s.model.geom_bodyid[c.geom1];b2=s.model.geom_bodyid[c.geom2]
 bn1=mujoco.mj_id2name(s.model,mujoco.mjtObj.mjOBJ_BODY,int(b1));bn2=mujoco.mj_id2name(s.model,mujoco.mjtObj.mjOBJ_BODY,int(b2))
 if 'robot_0' in (bn1 or '') or 'robot_0' in (bn2 or ''):
  f=np.zeros(6);mujoco.mj_contactForce(s.model,s.data,ci,f);contacts.append([g1,g2,bn1,bn2,float(c.dist),f.tolist(),c.pos.tolist()])
result={'status':s.status(),'tcp':s.proprio()['tcp_pose'].tolist(),'cabinet':{k:v for k,v in s.state()['joints'].items() if 'cabinet' in k},'contacts':contacts}
open('/app/output/probe_result.json','w').write(json.dumps(result,indent=2))
print('RESULT',json.dumps(result),flush=True)
import imageio.v3 as iio
iio.imwrite('/app/output/right_probe.png',s.render('randomized_gopro_analogue_1'))
